    lw(a3, a0, 4);
    lw(a2, a0, 8);
    lw(v0, a0, 12);
    v1 = sll(v0, 1);
    v0 = srl(a2, 31);
    v0 = v0 & 0x1;
    a1 = v1 | v0;
    v1 = sll(a3, 2);
    v0 = srl(t0, 30);
    v0 = v0 & 0x3;
    v0 = v1 | v0;
    v0 = v0 ^ a1;
